CREATE TABLE "t" (
  "id" integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "t_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
  "other_id" integer GENERATED BY DEFAULT AS IDENTITY,
  "is_done" boolean DEFAULT false NOT NULL,
  "sort" integer DEFAULT 0 NOT NULL,
  "coverage" numeric DEFAULT '0.5',
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "seen_on" date DEFAULT CURRENT_DATE,
  "starts_on" date DEFAULT '2026-01-01',
  "note" text DEFAULT '',
  "anchors" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "tags" jsonb DEFAULT '[]'::jsonb,
  "kind" text DEFAULT 'soft' NOT NULL,
  "parent_id" integer REFERENCES "t"("id") ON DELETE SET DEFAULT
);
